724→    if (isInDualView) {
725→      try {
726→        const leftIframe = document.getElementById("iframe-left");
727→        const src = leftIframe?.src || "/";
728→        let clean = src.replace(window.location.origin, "");
729→        clean = clean.replace(/[?&]embed=1/, "");
730→
731→        window.location.href = clean;
732→      } catch (err) {
733→        window.location.href = "/";
734→      }
735→    } else {
736→      const currentPath = window.location.pathname + window.location.search;
737→      const rightPanelDefault = "/";
738→      const hash = `#left:${encodeURIComponent(currentPath)}&right:${encodeURIComponent(rightPanelDefault)}`;
739→      window.location.href = `/dual${hash}`;
740→    }
741→  });
