745→<!-- Redirect links and searches when in dual view mode -->
746→<script>
747→document.addEventListener("DOMContentLoaded", function () {
748→  if (!window.location.pathname.startsWith("/dual")) return;
749→
750→  function getTargetPanel() {
751→    const selected = document.querySelector('input[name="targetPanel"]:checked');
752→    return selected ? selected.value : "left";
753→  }
754→
755→  function loadInPanel(panel, path) {
756→    if (!path) return;
757→    const iframe = document.getElementById(`iframe-${panel}`);
758→    if (!iframe) return;
759→    const url = path.includes("?") ? path + "&embed=1" : path + "?embed=1";
760→    iframe.src = url;
761→    const inputBox = document.querySelector(`#panel-${panel} input`);
762→    if (inputBox) inputBox.value = path;
763→    console.log(`Loaded "${url}" into panel "${panel}"`);
764→  }
765→  
766→  document.querySelectorAll(".dual-aware a[href^='/'], a.dual-aware[href^='/']").forEach(link => {
767→    link.addEventListener("click", function (e) {
768→      e.preventDefault();
769→      const path = this.getAttribute("href");
770→      loadInPanel(getTargetPanel(), path);
771→    });
772→  });
773→
774→  const idForm = document.getElementById("idsearchForm");
775→  if (idForm) {
776→    idForm.addEventListener("submit", function (e) {
777→      e.preventDefault();
778→      const input = idForm.querySelector(".idsearchTerm").value.trim();
779→      if (!input) return;
780→
781→      let path = null;
782→
783→      if (/^\d+$/.test(input)) {
784→        path = "/go_to/" + encodeURIComponent(input);
785→      } else if (/^((\d+|end)(-(\d+|end))?\s*)+(open|solved|yes|no)?$/i.test(input)) {
786→        const parts = input.split(/\s+/).filter(Boolean);
787→        path = "/range/" + parts.map(encodeURIComponent).join("/");
788→      } else {
789→        alert("Invalid input format.");
790→        return;
791→      }
792→
793→      loadInPanel(getTargetPanel(), path);
794→    });
795→  }
796→
797→  const searchForm = document.getElementById("searchForm");
798→  if (searchForm) {
799→    searchForm.addEventListener("submit", function (e) {
800→      e.preventDefault();
801→      const input = searchForm.querySelector(".searchTerm").value.trim();
802→      if (!input) return;
803→
804→      const path = "/search/" + encodeURIComponent(input);
805→      loadInPanel(getTargetPanel(), path);
806→    });
807→  }
808→});
809→</script>
